before:
pub(crate) mod context {
    use super::super::*;
    use semio_framework_plugin::artifact_app_laws::{meta, new_app_with_registry_and_members};
    use semio_framework_plugin::{App, EditorApp, InvocationResult, PluginApp, VcsArtifactApp, ViewModel};

    pub type WiresApp = VcsArtifactApp<EditorApp<ReasoningWiresPlayApp>, semio_s_artifact_stdio_semio::SemioMembers>;

    /// 🧪️ A registry-backed app bound to the live runtime instance `meta("local")` addresses. The registry-less
    /// `artifact_app_laws::new_app` cannot construct this app: its tool proofs need the manifest's `Migrated`
    /// classifications, and without them construction faults with `interactive-job.catalog-authority`.
    pub async fn new_app() -> OwnedWiresApp {
        let mut app = app_with_registry().await;
        app.bind_instance_id(meta("local").instance_id).await;
        app
    }

    /// 🧹️ Retires the app through its bounded close protocol instead of a panicking destructor.
    pub fn close(mut app: OwnedWiresApp) {
        app.close();
    }

    /// 🔚 A mounted app that RETIRES ITSELF. A live `ArtifactStore` asserts in `Drop`
    /// (`artifact store reached Drop without its exact terminal-empty shallow-shell witness`) unless
    /// it walked its bounded close loop first, so the fixture owns the close instead of asking every
    /// law to remember a trailing `close(&mut app)` — which is what makes a law that fails an
    /// assertion report ITS failure instead of a close panic. Skipped while unwinding, where the
    /// original panic is the report worth keeping. Derefs to the bare app for every read and dispatch.
    pub struct OwnedWiresApp(WiresApp);

    impl OwnedWiresApp {
        /// 🔚 Walks the bounded close protocol; idempotent (a terminal-empty app returns at once).
        pub fn close(&mut self) {
            semio_framework_plugin::artifact_app_laws::close_registered_fixture_app(&mut self.0);
        }
    }

    impl std::ops::Deref for OwnedWiresApp {
        type Target = WiresApp;
        fn deref(&self) -> &Self::Target {
            &self.0
        }
    }

    impl std::ops::DerefMut for OwnedWiresApp {
        fn deref_mut(&mut self) -> &mut Self::Target {
            &mut self.0
        }
    }

    impl Drop for OwnedWiresApp {
        fn drop(&mut self) {
            if !std::thread::panicking() {
                self.close();
            }
        }
    }

    /// 🧪️ Framework test context gap (SDK GAP, see this ticket's `📓️w0-f-report.md` handoff #3):
    /// `assert_declared_actions_bridge_to_commands`/`new_app_with_registry` still take `fn() -> App`,
    /// unchanged for this ticket, while `create_wires_app` now returns `AppDefinition` — this tiny
    /// local wrapper bridges the two shapes with an empty `examples` list (dropped per `create_wires_app`'s
    /// own doc comment).
    fn wires_manifest_for_tests() -> App {
        App { definition: create_wires_app(), examples: Vec::new() }
    }

    semio_framework_plugin::history_edit_acceptance_law!("reasoning", ReasoningWiresPlayApp, wires_manifest_for_tests, "../..");
    semio_framework_plugin::composed_reload_law!("reasoning", ReasoningWiresPlayApp, wires_manifest_for_tests, "../..");

    /// 🪆️ The app's live composed document (§20.15): its parent with the head of its board child.
    pub async fn composed(app: &WiresApp) -> crate::WiresComposed {
        let snapshot = app.snapshot().expect("snapshot");
        let packs = app.child_head_packs().await.expect("child head packs");
        let entry = packs.iter().find(|entry| entry.slot == crate::WIRES_CONTENT_SLOT && entry.child_id == snapshot.content.child_id).expect("the board child is composed");
        let content = <crate::SemioGraphSnapshot as store::ArtifactPack>::decode_pack(&entry.head_pack).expect("board head pack");
        crate::wires_composed(&snapshot, &content)
    }

    /// 🔎️ The composed board node `id` of the app's live document.
    pub async fn board_node(app: &WiresApp, id: &str) -> Option<semio_framework_value::DslValue> {
        crate::schema::board_node(&composed(app).await.board, id).cloned()
    }

    /// 🔢️ The `(nodes, edges)` counts of the app's live board.
    pub async fn board_counts(app: &WiresApp) -> (usize, usize) {
        let board = composed(app).await.board;
        (crate::schema::fixture_nodes(&board).len(), crate::schema::fixture_edges(&board).len())
    }

    /// 🧪️ An app wired to the real manifest registry — required to resolve the "graph" interaction
    /// domain's declaration when dispatching a framework-injected verb like `interactionSelect`.
    pub async fn app_with_registry() -> OwnedWiresApp {
        OwnedWiresApp(new_app_with_registry_and_members::<EditorApp<ReasoningWiresPlayApp>, semio_s_artifact_stdio_semio::SemioMembers>(wires_manifest_for_tests).await)
    }

    /// 🧪️ An app pre-loaded with the metabolism example document, for tests exercising a populated board.
    pub async fn metabolism_app() -> OwnedWiresApp {
        let mut app = new_app().await;
        let document = crate::schema::metabolism_wires_example_snapshot().expect("valid metabolism fixture mutations");
        let mut envelope = store::create_document_envelope::<WiresSnapshot, WiresMutation>(crate::MINDMAP_WIRES_SCHEMA, "reasoning-wires", document, None);
        envelope.dialect = Some(crate::WIRES_DIALECT.into());
        let files = store::print_document_pack(&envelope).await.expect("print document pack");
        retire_envelope(envelope);
        semio_framework_plugin::artifact_app_laws::load_document(&mut app, &files).await.expect("load metabolism");
        app
    }

    /// ♻️ Retires a seed envelope through its bounded owner retirement; an envelope may never reach `Drop` owning.
    pub fn retire_envelope(envelope: store::ArtifactEnvelope<WiresSnapshot, WiresMutation>) {
        let mut retirement = store::retire_document_envelope(envelope, std::sync::Arc::new(semio_framework_value::retirement::OwnedValueRetirementFactory::<WiresSnapshot>::default()), std::sync::Arc::new(semio_framework_value::retirement::OwnedValueRetirementFactory::<WiresMutation>::default()));
        while !matches!(retirement.close_step(1, store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES).expect("seed envelope retirement"), store::SnapshotRetirementStep::Complete) {}
        assert!(retirement.terminal_is_empty(), "seed envelope retires completely");
    }

    /// 🔁️ Drives one dispatched typed operation to quiescence the way the plugin host does — on a
    /// mounted app `dispatch_typed` only QUEUES the operation, so a law reading `app.snapshot()`
    /// straight afterwards would observe the pre-dispatch document, and the returned
    /// `InvocationResult` carries neither the mutations nor the effects the operation produces.
    pub async fn settle(app: &mut WiresApp) -> semio_framework_plugin::artifact_app_laws::TypedOperationFixtureReceipt {
        semio_framework_plugin::artifact_app_laws::settle_registered_typed_operation(app, meta("local").instance_id).await.expect("settle the typed operation")
    }

    /// 🧪️ Reads the actual declared board member through its current Store lease.
    pub fn board(app: &WiresApp) -> semio_framework_value::DslValue {
        use store::SpaceMember;
        let snapshot = app.snapshot().expect("current Wires parent");
        let member = semio_framework_async::poll::resolve_ready(app.child_store(crate::WIRES_CONTENT_SLOT, &snapshot.content.child_id)).expect("declared Wires child is registered");
        assert_eq!(member.artifact_ref().as_ref(), Some(&snapshot.content.target), "registered child keeps the exact declared target");
        let read = member.snapshot_read_erased_now().expect("current declared child read");
        let content = read.get::<crate::SemioGraphSnapshot>().expect("exact graph child type");
        crate::wires_composed(&snapshot, content).board
    }

    /// 📦️ Loads a parent and its explicit full graph child through the real recursive archive protocol.
    pub async fn load_graph_fixture(app: &mut WiresApp, nodes: Vec<semio_framework_value::DslValue>, edges: Vec<semio_framework_value::DslValue>) -> Result<(), semio_framework_plugin::Fault> {
        let content = crate::wires_content_snapshot(&nodes, &edges);
        let snapshot = WiresSnapshot { content: crate::wires_content_handle(&content), ..crate::empty_wires_snapshot() };
        let handle = snapshot.content.clone();
        let mut envelope = store::create_document_envelope::<WiresSnapshot, WiresMutation>(crate::MINDMAP_WIRES_SCHEMA, "reasoning-wires", snapshot, None);
        envelope.dialect = Some(crate::WIRES_DIALECT.into());
        let files = store::print_document_pack(&envelope).await.expect("graph fixture parent pack");
        retire_envelope(envelope);
        let mut archive = app.document_load_archive(&files)?;
        let parent = store::os_io::ArtifactRef { artifact_id: app.document_identity().expect("live parent identity"), dialect: crate::WIRES_DIALECT.into() };
        let owner = store::OwnerRef { parent: parent.clone(), slot: crate::WIRES_CONTENT_SLOT.into(), child_id: handle.child_id.clone() };
        let child_pack = store::ArtifactPack::encode_pack(&content);
        let envelope_pack = store::genesis_member_envelope_pack("stdio.semio", &handle.target, &owner, &child_pack).await.expect("full fixture child envelope");
        archive.members.push(protocol::OwnedDocumentMemberPackEntry {
            ordinal: 0,
            reference: protocol::DocumentArchiveArtifactRef { artifact_id: handle.target.artifact_id, artifact_kind: handle.target.dialect.artifact_kind, standard: handle.target.dialect.standard, subset: handle.target.dialect.subset },
            owner: protocol::DocumentArchiveOwnerRef { parent: protocol::DocumentArchiveArtifactRef { artifact_id: parent.artifact_id, artifact_kind: parent.dialect.artifact_kind, standard: parent.dialect.standard, subset: parent.dialect.subset }, slot: crate::WIRES_CONTENT_SLOT.into(), child_id: handle.child_id },
            envelope_pack,
        });
        let operation = semio_framework_plugin::artifact_app_laws::LAW_DOCUMENT_LOAD_OPERATION;
        app.begin_document_archive_load(operation, archive)?;
        for _ in 0..100_000 {
            let status = app.poll_document_archive_load(operation).await?;
            if matches!(status.state, protocol::DocumentArchiveLoadState::Pending | protocol::DocumentArchiveLoadState::Running) {
                continue;
            }
            app.acknowledge_document_archive_load(operation)?;
            assert_eq!(status.state, protocol::DocumentArchiveLoadState::Ready, "explicit graph fixture archive fault: {:?}", status.fault);
            return Ok(());
        }
        panic!("explicit graph fixture archive did not terminate");
    }

    /// 🎛️ Dispatches one typed command and settles its publication.
    pub async fn dispatch(app: &mut WiresApp, command: WiresCommand) -> InvocationResult {
        let result = app.dispatch_typed(command, &meta("local")).await.expect("dispatch");
        settle(app).await;
        result
    }

    /// 🎛️ Dispatches one typed command and hands back BOTH the invocation result and the receipt of
    /// the ONE settle that publishes it. A law reading `receipt.effects` must use this rather than
    /// `dispatch(..)` followed by `settle(..)`: `dispatch` already drains the operation, so a second
    /// settle finds `has_pending_typed_operations() == false` and answers an EMPTY receipt — no lanes,
    /// no effects — which reads exactly like a command that emitted nothing.
    pub async fn dispatch_receipt(app: &mut WiresApp, command: WiresCommand) -> (InvocationResult, semio_framework_plugin::artifact_app_laws::TypedOperationFixtureReceipt) {
        let result = app.dispatch_typed(command, &meta("local")).await.expect("dispatch");
        let receipt = settle(app).await;
        (result, receipt)
    }

    pub async fn render(app: &mut WiresApp, body_key: &str) -> String {
        let tree = app.render(body_key, None, &ViewModel::new(semio_framework_ui_locale::Locale::En, semio_framework_ui_locale::Terminology::Native)).await.expect("render");
        semio_framework_plugin::artifact_app_laws::project_and_retire_fixture_tree(tree).expect("retire rendered tree")
    }
}

use super::*;
use crate::editor::wires::unit_tests::context::{metabolism_app, new_app, render};
use semio_framework_plugin::EditorApp;
use serde_json::Value;

const RETAINED_ROUTES: &str = include_str!("../../🧫️fixtures/🛣️retained-command-routes.json");

#[test]
fn retained_route_fixture_matches_the_exact_factory_and_fail_closed_census() {
    use semio_framework_plugin::ArtifactOwnedToolJobFactory;
    let fixture: Value = serde_json::from_str(RETAINED_ROUTES).expect("Wires retained route fixture decodes through serde_json");
    assert_eq!(fixture.get("maximumRawBytes").and_then(Value::as_u64), Some(WIRES_RETAINED_RAW_BYTES as u64));
    assert_eq!(fixture.get("maximumWorkItems").and_then(Value::as_u64), Some(WIRES_RETAINED_WORK_ITEMS as u64));
    let routes = fixture.get("routes").and_then(Value::as_array).expect("routes");
    let migrated = routes.iter().filter(|route| route.get("disposition").and_then(Value::as_str) == Some("Migrated")).map(|route| route.get("id").and_then(Value::as_str).expect("route id")).collect::<Vec<_>>();
    assert_eq!(migrated, WIRES_RETAINED_TOOL_IDS);
    assert_eq!(routes.len(), 8);
    assert_eq!(<WiresRetainedCommandJobFactory as ArtifactOwnedToolJobFactory>::PUBLICATION_CONTRACTS, WIRES_RETAINED_PUBLICATION_CONTRACTS);
    // 🛣️ Keyed by tool id, not by ordinal: the roster grew from the three canvasPointer* rows to all
    // eight, so an index-based assertion pinned whichever row happened to sit at 0..2.
    for route in routes {
        let id = route.get("id").and_then(Value::as_str).expect("route id");
        let contract = WIRES_RETAINED_PUBLICATION_CONTRACTS.iter().find(|contract| contract.tool_id == id).unwrap_or_else(|| panic!("route {id} has no publication contract"));
        let declared: Vec<String> = contract.lanes.iter().map(|lane| format!("{lane:?}")).collect();
        let recorded: Vec<String> = route.get("lanes").and_then(Value::as_array).expect("route lanes").iter().map(|lane| lane.as_str().expect("lane name").to_string()).collect();
        assert_eq!(recorded, declared, "route {id} records lanes that differ from its publication contract");
    }
    assert!(routes.iter().filter(|route| route.get("disposition").and_then(Value::as_str) == Some("BatchOnlyPendingRewrite")).all(|route| route.get("lanes").and_then(Value::as_array).is_some_and(Vec::is_empty)));
}

//#region 🔖️CommandSurface
/// 🏷️ Every declared manifest action id must be reachable as exactly one command row, and every
/// row's wire keyword must be distinct — the cross-cutting invariant `app_commands!` is there to hold.
#[semio_framework_async_macros::async_test]
async fn command_ids_are_unique_and_match_the_declared_manifest_actions() {
    let commands = every_command();
    let ids: Vec<&str> = commands.iter().map(|command| command.command_id()).collect();
    let mut sorted = ids.clone();
    sorted.sort_unstable();
    sorted.dedup();
    assert_eq!(sorted.len(), ids.len(), "duplicate command ids in {ids:?}");
    assert_eq!(ids.len(), 8, "every WiresCommand row must be covered by every_command()");
}

/// ⚖️ LAW: text and binary are two projections of the same command, for every single row.
#[semio_framework_async_macros::async_test]
async fn every_command_round_trips_through_text_and_binary() {
    for command in every_command() {
        store::os_store::test_support::assert_op_text_binary_equivalence(&command);
    }
}

/// ⚖️ LAW: the leading token of every printed op line is the row's `dsl` wire keyword — pinned
/// per-row from the `app_commands!` table's `"id" as "wire-key"` declarations rather than derived
/// `setActiveExample` → `active-example`, and all three `canvasPointer*` rows drop the `canvas-`
/// prefix). This is what a missing `#[dsl(keyword = ..)]` on a payload struct silently breaks (the
/// record prints with no keyword at all and no longer parses).
#[semio_framework_async_macros::async_test]
async fn every_printed_op_line_starts_with_the_rows_wire_keyword() {
    let expected_keys = [
        ("setActiveExample", "active-example"),
        ("addNode", "add-node"),
        ("addRelationship", "add-relationship"),
        ("deleteSelection", "delete-selection"),
        ("canvasPointerMove", "pointer-move"),
        ("canvasPointerDown", "pointer-down"),
        ("canvasPointerUp", "pointer-up"),
        ("nodeGraphViewport", "node-graph-viewport"),
    ];
    for command in every_command() {
        let id = command.command_id();
        let expected = expected_keys.iter().find(|(row_id, _)| *row_id == id).map(|(_, key)| *key).unwrap_or_else(|| panic!("no expected wire key recorded for command {id}"));
        let printed = protocol::OpText::print_op(&command);
        assert_eq!(printed.split(' ').next().unwrap_or_default(), expected, "wire keyword drifted for command {id}: {printed:?}");
    }
}

/// ⚖️ The wire bytes/text pinned from the pre-merge 7-crate baseline (see the ticket's
/// `🧪️wire-baseline-before.txt`) — a regression here is a real format break, not a fixture mismatch.
/// `setSelection`/`documentSelect` dissolved into the framework's own "graph" interaction domain
/// (ticket 26/08/14/FIRST-CLASS-HOVER-AND-SELECTION-MECHANISM) and no longer exist as `WiresCommand`
/// pinned hex below are updated for the new ordinals; the synchronous `forceLayout`/`reorganize` rows dissolved into the
/// `reorganize` tool run (ticket 26/09/13/INTERACTIVE-TOOLS-VISIBLE-PROCESS); `SetActiveExample` is unaffected
/// (ordinal 0, before the deleted rows). `CanvasPointerUp` gained the trailing `cancelled` flag
/// (ticket 26/09/16/INPUT-CAUSALITY-LEDGER §2 D — gesture cancel), so its pinned text/hex carry
/// the appended bool (`...0001` = one field, `false`); the ordinal is unchanged.
#[semio_framework_async_macros::async_test]
async fn commands_keep_their_pre_migration_wire_bytes() {
    let cases: [(WiresCommand, &str, &str); 2] = [
        (WiresCommand::SetActiveExample(set_active_example::SetActiveExample { example_id: "metabolism".into() }), "active-example active-example example-id=metabolism", "0100010a6d657461626f6c69736d01000600"),
        (WiresCommand::CanvasPointerUp(canvas_pointer_up::CanvasPointerUp { cancelled: false }), "pointer-up pointer-up cancelled=false", "010600010001"),
    ];
    for (command, text, hex) in cases {
        assert_eq!(protocol::OpText::print_op(&command), text);
        assert_eq!(protocol::OpBinary::encode_op(&command).expect("encode").iter().map(|b| format!("{b:02x}")).collect::<String>(), hex);
        store::os_store::test_support::assert_op_text_binary_equivalence(&command);
    }
}

/// 🧾️ One representative value per row, in declaration (= binary ordinal) order.
pub(super) fn every_command() -> Vec<WiresCommand> {
    vec![
        WiresCommand::SetActiveExample(set_active_example::SetActiveExample { example_id: "metabolism".into() }),
        WiresCommand::AddNode(add_node::AddNode { kind: "identity".into() }),
        WiresCommand::AddRelationship(add_relationship::AddRelationship { kind: "owns".into(), source_id: "node-1".into(), target_id: "node-2".into() }),
        WiresCommand::DeleteSelection(delete_selection::DeleteSelection {}),
        WiresCommand::CanvasPointerMove(canvas_pointer_move::CanvasPointerMove { x: 1.5, y: -2.5, samples: vec![[0.5, -1.5], [1.5, -2.5]] }),
        WiresCommand::CanvasPointerDown(canvas_pointer_down::CanvasPointerDown { id: Some("node-1".into()), x: 10.0, y: 20.0 }),
        WiresCommand::CanvasPointerUp(canvas_pointer_up::CanvasPointerUp { cancelled: false }),
        WiresCommand::NodeGraphViewport(node_graph_viewport::NodeGraphViewport { viewport: semio_framework_os_kernel::Viewport2d { x: 1.0, y: 2.0, zoom: 1.5 } }),
    ]
}
//#endregion 🔖️CommandSurface

//#region 🔖️Interaction
/// 🕹️ The "graph" domain is declared `HierarchyProvider::Flat`, single-select/pick/replace-only,
/// and scoped to the canvas window (ticket 26/08/14/FIRST-CLASS-HOVER-AND-SELECTION-MECHANISM).
